import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.DQvKz0xt.js";const g=JSON.parse('{"title":"检查器 (Inspector) - Rive 编辑器","description":"检查器位于编辑器的右侧。它显示了 Rive 编辑器中所有对象的所有可编辑属性。 对象的待编辑属性可以在检查器中找到。检查器会根据你选择的对象以及你在编辑器中所处的位置动态变化。","frontmatter":{"title":"检查器 (Inspector) - Rive 编辑器","description":"检查器位于编辑器的右侧。它显示了 Rive 编辑器中所有对象的所有可编辑属性。 对象的待编辑属性可以在检查器中找到。检查器会根据你选择的对象以及你在编辑器中所处的位置动态变化。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 界面面板, 检查器"}]]},"headers":[],"relativePath":"editor/interface-overview/inspector.md","filePath":"editor/interface-overview/inspector.md","lastUpdated":1774838907000}'),o={name:"editor/interface-overview/inspector.md"};function n(p,e,s,l,d,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<p>界面概览</p><h1 id="检查器-inspector" tabindex="-1">检查器 (Inspector) <a class="header-anchor" href="#检查器-inspector" aria-label="Permalink to &quot;检查器 (Inspector)&quot;">​</a></h1><p>检查器位于编辑器的右侧。它显示了 Rive 编辑器中所有对象的所有可编辑属性。</p><h1 id="​-检查器-inspector" tabindex="-1"><a href="#inspector">​</a> 检查器 (Inspector) <a class="header-anchor" href="#​-检查器-inspector" aria-label="Permalink to &quot;[​](#inspector) 检查器 (Inspector)&quot;">​</a></h1><p>对象的待编辑属性可以在检查器中找到。检查器会根据你选择的对象以及你在编辑器中所处的位置动态变化。 <img src="https://help.rive.app/images/inspector.png" alt="检查器示例 Pn"></p><h2 id="​-背景颜色、标签、默认插值" tabindex="-1"><a href="#background-color,-tags,-default-interpolation">​</a> 背景颜色、标签、默认插值 <a class="header-anchor" href="#​-背景颜色、标签、默认插值" aria-label="Permalink to &quot;[​](#background-color,-tags,-default-interpolation) 背景颜色、标签、默认插值&quot;">​</a></h2><p>当没有选中任何内容时，检查器包含三个部分：背景、标签和默认插值 (Default Interpolation)。</p><p><strong>背景颜色 (Background color)</strong> 该部分位于检查器顶部，允许你更改动画 (Animate) 和设计 (Design) 模式下编辑器的背景颜色。这是一个提醒你当前处于哪种模式的有用方法。 <img src="https://help.rive.app/images/backgrounds.png" alt="背景颜色设置 Pn"></p><p><strong>标签 (Tags)</strong> 在背景颜色下方，你可以查看、编辑和向文件添加新标签。在此处了解更多关于标签的信息：<a href="/docs/editor/tagging">此处</a>。 <img src="https://help.rive.app/images/tags.png" alt="标签管理 Pn"></p><p><strong>默认插值 (Default Interpolation)</strong> 标签下方是文件的默认插值设置。 <img src="https://help.rive.app/images/default_Int.png" alt="默认插值设置 Pn"> 当你在时间轴上设置一个关键帧时，它将使用文件的默认插值，直到在时间轴上再次更改。通过更改默认插值，你可以控制应用于新关键帧的插值曲线。</p><h2 id="​-对齐和分布工具-align-and-distribute-tools" tabindex="-1"><a href="#align-and-distribute-tools">​</a> 对齐和分布工具 (Align and Distribute tools) <a class="header-anchor" href="#​-对齐和分布工具-align-and-distribute-tools" aria-label="Permalink to &quot;[​](#align-and-distribute-tools) 对齐和分布工具 (Align and Distribute tools)&quot;">​</a></h2><p>当选中一个或多个对象（如形状或分组）时，对齐工具会出现在检查器顶部。使用它们来对齐或分布所选对象。在“对齐工具”页面了解更多。 <img src="https://help.rive.app/images/Align.png" alt="对齐工具 Pn"></p><h2 id="​-布局和-n-切片-layout-and-n-slicing" tabindex="-1"><a href="#layout-and-n-slicing">​</a> 布局和 N-切片 (Layout and N-Slicing) <a class="header-anchor" href="#​-布局和-n-切片-layout-and-n-slicing" aria-label="Permalink to &quot;[​](#layout-and-n-slicing) 布局和 N-切片 (Layout and N-Slicing)&quot;">​</a></h2><p>当选中一个或多个对象（如形状或分组）时，检查器提供对当前选择进行布局 (Layout) 或 N-切片 (N-Slice) 的选项。 <img src="https://help.rive.app/images/LOandN.png" alt="布局和切片选项 Pn"></p><p>[## 布局 (Layouts)</p><p><a href="/docs/editor/layouts/overview">布局让你能够构建响应式设计。</a>[## N-切片 (N-Slicing)</p><p><a href="/docs/editor/layouts/n-slicing">N-切片让你能够拉伸或重复位图和矢量设计的某些部分。</a></p><h2 id="​-变换属性-transform-properties" tabindex="-1"><a href="#transform-properties">​</a> 变换属性 (Transform properties) <a class="header-anchor" href="#​-变换属性-transform-properties" aria-label="Permalink to &quot;[​](#transform-properties) 变换属性 (Transform properties)&quot;">​</a></h2><p>对象的变换属性出现在对齐工具下方。通常，这些属性包括位置 (Position)、缩放 (Scale) 和旋转 (Rotation)，但如果你选中了路径层，它们还可能包括宽度 (Width) 和高度 (Height)。 <img src="https://help.rive.app/images/Transform.png" alt="变换属性 Pn"></p><h2 id="​-图层属性-layer-properties" tabindex="-1"><a href="#layer-properties">​</a> 图层属性 (Layer properties) <a class="header-anchor" href="#​-图层属性-layer-properties" aria-label="Permalink to &quot;[​](#layer-properties) 图层属性 (Layer properties)&quot;">​</a></h2><p>变换属性下方有几个属性，允许你自定义舞台上某些对象的外观。这些属性包括混合模式 (Blend mode)、不透明度 (Opacity)、填充 (Fill) 和描边 (Stroke)。 <img src="https://help.rive.app/images/Layer.png" alt="图层属性 Pn"></p><h2 id="​-其他属性-additional-properties" tabindex="-1"><a href="#additional-properties">​</a> 其他属性 (Additional properties) <a class="header-anchor" href="#​-其他属性-additional-properties" aria-label="Permalink to &quot;[​](#additional-properties) 其他属性 (Additional properties)&quot;">​</a></h2><p>在图层属性下方，你会发现许多可以添加的其他属性，例如剪裁 (Clipping)、约束 (Constraints)、自定义绘制顺序 (Custom Draw Order) 和选择颜色 (Selection Colors)。 <img src="https://help.rive.app/images/additional.png" alt="其他属性 Pn"></p><p>[## 操纵形状 (Manipulating Shapes)</p><p>Rive 编辑器提供了多种方式来操纵图形，以创建所需的动画。](../manipulating-shapes/manipulating-shapes)[## 约束 (Constraints)</p><p><a href="https://help.rive.app/editor/manipulating-shapes/constraints" target="_blank" rel="noreferrer">约束是通过另一个目标对象来控制一个对象属性的一种方式。</a>[## 动画模式 (Animate Mode)</p><p><a href="https://help.rive.app/editor/animate-mode/overview" target="_blank" rel="noreferrer">Rive 有两种不同的模式：设计 (Design) 和动画 (Animate)。</a></p><h3 id="​-运动和状态属性-motion-and-state-properties" tabindex="-1"><a href="#motion-and-state-properties">​</a> 运动和状态属性 (Motion and State Properties) <a class="header-anchor" href="#​-运动和状态属性-motion-and-state-properties" aria-label="Permalink to &quot;[​](#motion-and-state-properties) 运动和状态属性 (Motion and State Properties)&quot;">​</a></h3><p>当选中关键帧、过渡 (Transitions) 或状态 (States) 时，此部分会显示可自定义的属性。 <img src="https://help.rive.app/images/motioninspector.png" alt="运动检查器 Pn"></p><p>[## 插值面板 (Interpolation Panel)</p><p><a href="https://help.rive.app/editor/animate-mode/interpolation-easing" target="_blank" rel="noreferrer">选中关键帧会弹出插值面板。</a>[## 过渡属性 (Transition Properties)</p><p><a href="/docs/editor/state-machine/transitions">选择一个过渡将显示可自定义的过渡属性。</a>[## 状态属性 (State Properties)</p><p><a href="/docs/editor/state-machine/states">通过选择一个状态可以自定义状态属性。</a></p>',33)])])}const m=a(o,[["render",n]]);export{g as __pageData,m as default};
